input.command:
cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

// Observable failure contract (chosen reading, not stated by the spec):
// the domain layer throws an Error with a descriptive message; src/cli.ts
// translates that into a non-zero exit status plus a stderr description.

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest cases and base premiums ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");
  it.todo("quotes a single plain sword -- base 100 G + 5 G fee = 105 G");
  it.todo("quotes a single plain amulet -- base 60 G + 5 G fee = 65 G");
  it.todo("quotes a single plain staff -- base 80 G + 5 G fee = 85 G");
  it.todo("quotes a single plain potion -- base 40 G + 5 G fee = 45 G");
  it.todo("quotes a single rune -- base 25 G + 5 G fee = 30 G");
  it.todo("quotes a single moonstone -- base 25 G + 5 G fee = 30 G");

  // --- Component building blocks (exactly 3 alike) ---
  it.todo("quotes 2 runes -- 50 G base premium (no block)");
  it.todo("quotes 3 runes -- 60 G base premium (block applies)");
  it.todo("quotes 4 runes -- 100 G base premium (no block; block requires exactly 3)");
  it.todo("quotes 7 runes -- 175 G base premium");
  it.todo("quotes 2 runes + 1 moonstone -- 75 G base premium (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones -- 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("applies 50% curse surcharge to the cursed item's base premium -- cursed sword base 150 G");
  it.todo("applies 30% high-enchantment surcharge at enchantment exactly 5 -- sword base 130 G");
  it.todo("applies no high-enchantment surcharge at enchantment 4 -- sword base 100 G");
  it.todo("applies both curse and high-enchantment surcharges when cursed at enchantment exactly 5 -- sword base 180 G");
  it.todo("scopes the curse surcharge to the cursed item only -- cursed sword + plain amulet = 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies 20% loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies 10% first-insurance surcharge on the policy base premium");
  it.todo("applies 15% follow-up discount on each contract after the customer's first");
  it.todo("applies the first-insurance surcharge on a follow-up contract too (each quote's items are first insurances)");

  // --- Rounding (premium up, payout down, only at the end) ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote integration examples ---
  it.todo("quotes newcomer with a cursed sword -- 100 base + 50 curse + 10 first = 160 + 5 fee = 165 G");
  it.todo("quotes long-standing customer's second contract, cursed sword enchantment 7 -- 155 + 5 fee = 160 G");

  // --- Quote rejection ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- throws Error, no results written");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out a regular sword (steel, enchantment 3) damage 500 G -- payout 400 G (500 - 100 deductible)");
  it.todo("pays out rune damage 200 G -- payout 100 G (no enchantment or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G = payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses 50% for damage at enchantment exactly 8 -- dragon sword, damage 1000 G, payout 400 G");
  it.todo("fully reimburses dragon material at enchantment 5 -- damage 800 G, payout 700 G");
  it.todo("prefers the 50% rule over dragon material at enchantment 9 -- damage 1000 G, payout 400 G");
  it.todo("applies only the high-enchantment clause for a steel sword at enchantment 9 -- damage 1000 G, payout 400 G");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy at twice the insurance sum -- sword + amulet: sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance value -- cursed sword: cap 2000 G despite 165 G premium");
  it.todo("excludes the block discount from the insurance sum -- sword + 3 runes: sum 1750 G");
  it.todo("covers two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("treats each damage entry of the same type as a separate damage with its own deductible");
  it.todo("reduces the payout to the remaining cap -- first claim 1500 G pays 1400 G, remaining cap 600 G");
  it.todo("pays only the remaining cap on a second claim -- second claim 1500 G pays 600 G, remaining cap 0 G");

  // --- Claim rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only sword insured) -- throws Error");
  it.todo("rejects a claim with an unknown damaged item type -- throws Error");
  it.todo("rejects a claim with more damage entries of a type than the policy covers -- throws Error");
  it.todo("rejects a claim with a negative damage amount (-200) -- throws Error");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI processes the schema example -- quote then claim against policy 0");
  it.todo("CLI exits non-zero and writes an error description to stderr on an invalid scenario");
});
EOF
echo "written"; grep -c "it.todo" src/claim-office.spec.ts

