export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
}

const DEDUCTIBLE_G = 100;
const REDUCED_REIMBURSEMENT_LEVEL = 8;
const REDUCED_REIMBURSEMENT_RATE = 0.5;

function reimbursementRate(item: Item): number {
  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_LEVEL ? REDUCED_REIMBURSEMENT_RATE : 1;
}

function damagePayout(item: Item, damage: Damage): number {
  return damage.amount * reimbursementRate(item) - DEDUCTIBLE_G;
}

export function claim(policy: Item[], incident: Incident): ClaimResult {
  const total = incident.damages.reduce((sum, damage) => {
    const item = policy.find((candidate) => candidate.type === damage.itemType) as Item;
    return sum + damagePayout(item, damage);
  }, 0);
  return { payout: roundPayoutInMHPCOsFavour(total) };
}
'''
